class Solution {
    public int longestNiceSubarray(int[] nums){
        int mask=0,left=0,answer=0;
        for(int right=0;right<nums.length;right++){
            while((mask&nums[right])!=0)mask^=nums[left++];
            mask|=nums[right];
            answer=Math.max(answer,right-left+1);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestNiceSubarray(nums:IntArray):Int{
        var mask=0;
        var left=0;
        var answer=0;
        for(right in nums.indices){
            while(mask and nums[right]!=0)mask=mask xor nums[left++];
            mask=mask or nums[right];
            answer=maxOf(answer,right-left+1)
        };
        return answer
    }
}

